    "You are a customer service agent. Respond politely and clearly in English.",
  "falar com humano": "talk to a person",
  atendente: "human agent",
  "pessoa real": "real person",
  "Atender e responder": "Handle and reply",
  "O agente lê a conversa, entende o histórico e responde ao cliente sem pedir que ele repita o que já disse.":
    "The agent reads the conversation, understands its history, and replies without asking the customer to repeat information.",
  "Vender e mover o funil": "Sell and update the funnel",
  "O agente registra a oportunidade, atualiza o negócio e move o cliente de etapa conforme a conversa avança.":
    "The agent records the opportunity, updates the deal, and moves the customer through stages as the conversation progresses.",
  "Não perder o cliente": "Keep the customer engaged",
  "O agente agenda retornos e acompanha quem esfriou, para que nenhum interessado morra por falta de resposta.":
    "The agent schedules follow-ups and tracks cooling leads so no interested customer is lost through lack of a response.",
  "Passar para um humano": "Hand off to a person",
  "O agente reconhece quando não é o caso dele resolver, chama uma pessoa e entrega o resumo do que já aconteceu.":
    "The agent recognizes when a person needs to take over and hands off a summary of what has already happened.",
  "Organizar a operação": "Organize operations",
  "O agente mantém a casa em ordem: marcadores, etapas do funil, avisos automáticos e distribuição de trabalho.":
    "The agent keeps operations organized: tags, funnel stages, automatic alerts, and work assignment.",
  "Aprender e evoluir": "Learn and improve",
  "O agente consulta o que a empresa já sabe, aprende com os atendimentos e sugere melhorias para você aprovar.":
    "The agent uses company knowledge, learns from conversations, and suggests improvements for your approval.",
