  "Quando mais de um agente puder atender a mesma conversa, o de número maior tenta primeiro. Se você só tem um agente, pode deixar como está.":
    "When more than one agent can handle the same conversation, the one with the highest number tries first. If you only have one agent, you can leave it as is.",
