  "— ele não sabe organizar este funil ainda": "— he doesn’t know how to organize this funnel yet",
  "Sem nenhum funil marcado, ele conversa com os clientes normalmente, mas não mexe em negócio nenhum — nem move, nem encerra, nem marca.":
    "Without any funnel marked, he talks to customers normally, but doesn't touch any business — neither moves, nor closes, nor marks.",
  "Você marcou": "You scored",
  ", mas ninguém disse ao assistente o que cada etapa desse funil significa — ele vai atender e deixar os negócios parados onde estão.":
    ", but no one told the assistant what each stage of this funnel means — he will respond and leave the business where it is.",
  "funis em que ninguém disse ao assistente o que cada etapa significa — ele vai atender e deixar os negócios parados onde estão.":
    "funnels where no one told the assistant what each step means — he will answer and leave the business where it is.",
  " Isso se configura em Configurações › Funis.": "This is configured in Settings › Funnels.",
  "As conversas novas viram negócio em": "New conversations turn into business",
  ", que não está marcado. O assistente vai atender e os negócios vão se acumular ali sem que ele possa organizá-los.":
    ", which is not marked. The assistant will answer and business will accumulate there without him being able to organize it.",
  "Carregando fluxos publicados…": "Loading published streams…",
  "Erro ao carregar fluxos.": "Error loading streams.",
  "Nenhum fluxo publicado ainda.": "No streams published yet.",
