  "Máximo de 20 fluxos por agent.": "Maximum 20 flows per agent.",
  "O que faz ele responder": "What makes him respond?",
  "Uma mensagem nova do cliente": "A new message from the customer",
  "Não responder em grupos": "Do not respond in groups",
  "Não responder às mensagens que saem do seu próprio número":
    "Do not respond to messages from your own number",
  "Só responder quando a mensagem falar de algo específico (opcional)":
    "Only respond when the message talks about something specific (optional)",
  "Ex.: pedido|status|orçamento": "E.g.: order|status|budget",
  "Deixe em branco para o agente responder a tudo. Se preencher, ele só entra quando a mensagem contiver uma dessas palavras — separe por barra vertical (|). Aceita expressão regular, para quem já conhece.":
    "Leave it blank for the agent to respond to everything. If you fill it in, it only enters when the message contains one of these words — separate it with a vertical bar (|). Accepts regular expression, for those who already know.",
  "Quantos atendimentos ao mesmo tempo": "Concurrent conversations",
