  "Aguardando solicitação de remarcação.": "Waiting for a rescheduling request.",
  "Retome a proposta com educação, ofereça ajuda e pergunte se existe alguma dúvida. Não invente preço, prazo ou condição.":
    "Follow up on the proposal politely, offer help, and ask whether they have any questions. Do not invent prices, deadlines, or terms.",
  "Faça uma última tentativa breve e respeitosa. Deixe claro que a pessoa pode retomar a conversa quando quiser. Não pressione.":
    "Make one last brief, respectful attempt. Make it clear that the person can restart the conversation whenever they want. Do not pressure them.",
  "Retome a conversa de forma breve e útil, usando apenas o contexto já confirmado. Faça uma pergunta simples e não pressione.":
    "Restart the conversation briefly and helpfully, using only confirmed context. Ask one simple question and do not pressure them.",
  "Lembre o contato de forma prestativa que o checkout ficou pendente e ofereça ajuda. Não invente disponibilidade, desconto ou link.":
    "Helpfully remind the contact that checkout is still pending and offer assistance. Do not invent availability, discounts, or links.",
  "Ofereça ajuda uma última vez, de forma curta e sem pressão. Use somente dados confirmados da conversa.":
    "Offer help one last time, briefly and without pressure. Use only confirmed conversation data.",
  "Pergunte com empatia se a pessoa deseja remarcar. Não confirme horário sem consultar a agenda e não atribua culpa.":
    "Ask empathetically whether the person wants to reschedule. Do not confirm a time without checking the calendar, and do not assign blame.",
