  "Atualização do caso": "Case update",
  "Um roteador entende o que o cliente quer e entrega a conversa para o agente certo — plugado em um número de WhatsApp.":
    "A router understands what the customer wants and delivers the conversation to the right agent — plugged into a WhatsApp number.",
  "Novo roteador": "New router",
  "Um roteador entende o que o cliente quer e entrega a conversa para o agente certo — um número de vendas fala com quem quer comprar, um de suporte com quem já é cliente, tudo no mesmo WhatsApp. Crie um para o seu número e escolha quais agentes ele aciona.":
    "A router understands what the customer wants and delivers the conversation to the right agent — a sales number speaks to those who want to buy, a support number speaks to those who are already customers, all in the same WhatsApp. Create one for your number and choose which agents it triggers.",
  "Criar meu primeiro roteador": "Create my first router",
  "Número removido": "Number removed",
  "Sem intenções configuradas": "No intentions configured",
  intenção: "Intention",
  intenções: "Intentions",
  "Roteador criado — agora escolha as intenções.": "Router created — now choose intentions.",
  "Escolha o número de WhatsApp que ele vai atender. Depois de criado, você define as intenções e para qual agente cada uma vai.":
    "Choose the WhatsApp number he will answer. Once created, you define the intentions and which agent each one goes to.",
  "Número de WhatsApp": "WhatsApp number",
  "Só é possível ter um roteador ativo por número.":
    "It is only possible to have one active router per number.",
  "Criar roteador": "Create router",
  ativo: "active",
  inativo: "Inactive",
  "Excluir roteador": "Delete router",
  Identificação: "Identification",
  "O número não pode ser trocado depois de criado — crie outro roteador para um número diferente.":
    "The number cannot be changed once created — create another router for a different number.",
  "Ativo — está roteando as conversas deste número":
    "Active — is routing conversations from this number",
  "Inativo — não roteia nada": "Inactive — does not route anything",
  "Modelo que identifica a intenção": "Model that identifies intent",
  "Modelo do classificador": "Classifier model",
  "Automático — usa o provedor da organização": "Automatic — uses the organization's provider",
  "chave desta instalação": "key for this installation",
  "Nenhuma chave de IA utilizável nesta organização — cadastre uma em Agentes IA › Credenciais para poder escolher o modelo.":
    "No AI keys usable in this organization — register one in AI Agents › Credentials to choose the model.",
  "Só aparecem modelos de provedores com chave cadastrada aqui. Se a conta do provedor estiver sem crédito, a identificação falha e tudo cai no fallback.":
    "Only models from providers with a key registered here appear. If the provider's account is out of credit, identification fails and everything goes into fallback.",
  "Se nenhuma intenção casar": "If no intention to marry",
  "Agente de fallback": "Fallback Agent",
  "Nenhum — responde com o atendimento padrão": "None — responds with standard service",
  "Quando a IA não tem certeza do que o cliente quer, ela chama este agente em vez de travar a conversa.":
    "When the AI ​​isn't sure what the customer wants, it calls this agent instead of holding the conversation.",
  Intenções: "Intentions",
  "Cada intenção descreve uma situação e diz qual agente deve assumir a conversa quando o cliente quer aquilo.":
    "Each intent describes a situation and tells which agent should take over the conversation when the customer wants that.",
  Intenção: "Intention",
  "Nenhuma intenção ainda. Sem intenções, toda conversa cai direto no agente de fallback (ou fica sem resposta automática, se você não escolher um).":
    "No intentions yet. Without intentions, every conversation falls straight to the fallback agent (or becomes unresponsive if you don't choose one).",
  "O número volta a ser atendido pelos gatilhos normais dos agentes (sem roteamento por intenção). As intenções deste roteador são apagadas junto. Não é possível desfazer.":
    "The number is returned to the agents' normal triggers (without intention routing). This router's intentions are erased along with it. Cannot undo.",
