  "A proteção de gasto está desligada nesta instalação (AI_BUDGET_ENFORCEMENT=off). O que estiver escolhido aqui não vale enquanto quem cuida do servidor não religar.":
    "Spend protection is turned off in this installation (AI_BUDGET_ENFORCEMENT=off). Whatever is chosen here is not valid until whoever takes care of the server reconnects it.",
  "Abrimos um aviso na Central de avisos. A IA continua respondendo normalmente.":
    "We have opened a notice in the Notice Center. The AI ​​continues to respond normally.",
