  'Nenhum aprendizado ainda. Use "+ Novo aprendizado" para ensinar algo que os agentes devem lembrar em toda conversa — ou aguarde o sistema sugerir aprendizados automaticamente a partir do atendimento real.':
    'No learning yet. Use "+ New learning" to teach something that agents must remember in every conversation — or wait for the system to automatically suggest learnings from the actual service.',
  "Nenhum aprendizado arquivado.": "No learning archived.",
  "Nenhum aviso em aberto": "No open notices",
