  "Nenhuma conversa foi classificada por assunto. Os assuntos são os que você cadastra no roteador do seu número.":
    "No conversations were classified by topic. The subjects are those that you register on your number's router.",
  "Nenhuma conversa foi encaminhada. Isso só acontece em números que têm um roteador configurado — sem ele, tudo cai no atendimento padrão.":
    "No conversation was forwarded. This only happens on numbers that have a router configured — without it, everything falls into standard service.",
