  "Nenhuma versão publicada ainda": "No version published yet",
  'Nesta instalação a proteção só avisa (AI_BUDGET_ENFORCEMENT=avisar): mesmo com "Parar a IA" escolhido, ela vai continuar respondendo.':
    'In this installation, the protection only warns (AI_BUDGET_ENFORCEMENT=warn): even with "Stop AI" chosen, it will continue to respond.',
  "Novo aprendizado": "New learning",
  "Não consegui carregar a configuração de IA": "I was unable to load the AI configuration",
  "Não consegui carregar as execuções": "I was unable to load the executions",
  "Não conseguimos carregar os números agora. Recarregue a página em alguns instantes — se continuar assim, avise quem cuida da sua instalação.":
    "We are unable to load the numbers now. Reload the page in a few moments — if it continues like this, notify whoever takes care of your installation.",
  "O agente não consultou seus materiais. Ou não há nada publicado na base de conhecimento, ou as conversas não chegaram a precisar.":
    "The agent did not consult his materials. Either there is nothing published in the knowledge base, or the conversations were not accurate.",
  "O catálogo deste provedor ainda não foi baixado. Digite o identificador do modelo como o provedor o nomeia — a lista completa aparece sozinha depois da primeira sincronização.":
    "This provider's catalog has not yet been downloaded. Enter the model identifier as the provider names it — the full list appears on its own after the first synchronization.",
