  "Você ainda não cadastrou nenhuma chave de provedor. Enquanto isso, tudo usa a chave que veio na instalação.":
    "You have not yet registered any provider keys. Meanwhile, everything uses the key that came with installation.",
  "Volume de texto processado por dia": "Volume of text processed per day",
  "a cada 100": "every 100",
  "a maioria responde em": "most respond in",
  "agora usa": "now use",
  "aprendido automaticamente": "learned automatically",
  ativa: "Active",
