  caracteres: "characters",
  'carregado no editor. Clique em "Publicar versão" para confirmar.':
    'loaded in the editor. Click "Publish Version" to confirm.',
  código: "Code",
  "da instalação": "of installation",
  "depois de salvar. É o tempo de você ver o aviso chegar antes que alguma conversa pare.":
    "after saving. It's time for you to see the warning come before any conversation stops.",
  "desinstalada.": "uninstalled.",
  "do catálogo": "from the catalog",
  "do limite": "from the limit",
  "do limite. A IA não para.": "of the limit. AI doesn't stop.",
  "enviada e instalada com sucesso.": "sent and installed successfully.",
