  "Números desconectados aparecem desabilitados — reconecte em Conexões antes de usar.":
    "Disconnected numbers appear disabled — reconnect in Connections before use.",
  "Oi {{nome}}, tudo bem?": "Hi {{nome}}, how are you?",
  "Respeitamos a janela de envio e o limite diário configurados para esse número em Conexões — fora da janela, a mensagem espera a próxima.":
    "We respect the sending window and daily limit configured for this number in Connections — outside the window, the message waits for the next one.",
  "Qual agente escreve": "Which agent writes",
  "não publicado": "Unpublished",
  "Nenhum agente está publicado. Publique um em Agentes de IA para poder usá-lo aqui.":
    "No agents are published. Post one to AI Agents so you can use it here.",
  "Ele escreve com o mesmo tom e o mesmo conhecimento que usa no atendimento.":
    "He writes with the same tone and the same knowledge he uses in customer service.",
  "O que a IA deve fazer com os dados": "What AI should do with data",
  "Ex.: Agradeça o interesse citando o segmento que a pessoa informou, mostre em uma frase como a gente resolve a dificuldade que ela descreveu, e pergunte qual o melhor horário para conversar.":
    "Ex.: Thank them for their interest by citing the segment that the person reported, show in one sentence how we resolve the difficulty they described, and ask what is the best time to talk.",
  "O agente já sabe que é a PRIMEIRA mensagem, logo depois de a pessoa preencher o formulário, e recebe todos os campos que ela respondeu. Aqui você diz o que fazer com eles — quanto mais concreto, melhor a mensagem.":
    "The agent already knows that it is the FIRST message, right after the person fills out the form, and receives all the fields that they responded to. Here you say what to do with them — the more concrete, the better the message.",
