  "Proteção de envio —": "Shipping Protection —",
  "Estes limites protegem o número contra bloqueio do WhatsApp. Campo vazio usa o padrão seguro do sistema (mostrado no campo).":
    "These limits protect the number from being blocked by WhatsApp. Empty field uses the system's secure default (shown in the field).",
  "A ordem de preferência vai de 0 a 1000.": "The order of preference goes from 0 to 1000.",
  "Este número é usado desde": "This number has been used since",
  "A conexão pode ser nova sem que o número seja. O aquecimento conta a idade do NÚMERO — em branco, ele é tratado como recém-criado e começa liberando pouco por dia. Uma data já salva não some se você limpar o campo: para mudá-la, informe outra.":
    "The connection may be new without the number being. Heating counts the age of the NUMBER — in white, it is treated as newly created and starts releasing little per day. A date already saved does not disappear if you clear the field: to change it, enter another one.",
  "Este número já está aquecido — pular o aquecimento":
    "This number is already warmed up — skip warming up",
  "Vale só o teto diário abaixo. Use apenas se o número já envia há semanas: pular o aquecimento num número novo é o caminho mais rápido para o bloqueio.":
    "Only the daily ceiling below is worth it. Only use if the number has been sending for weeks: skipping the warm-up on a new number is the quickest way to getting blocked.",
  "Número com": "Number with",
  "dia(s) de uso — já formado. Vale só o teto diário abaixo.":
    "day(s) of use — already formed. Only the daily ceiling below is worth it.",
  "Hoje o aquecimento libera": "Today the heating releases",
  "envio(s) — o número tem": "shipment(s) — the number has",
  "dia(s) de uso. Enquanto esse número for menor que o teto diário, é ELE que limita, e mexer no teto diário não muda nada.":
    "day(s) of use. As long as this number is lower than the daily ceiling, it is HE that limits it, and changing the daily ceiling doesn't change anything.",
  "Janela de envio (horário local)": "Submission window (local time)",
  "Hora de início da janela": "Window start time",
  "h até": "h until",
  "Hora de fim da janela": "Window end time",
  "O assistente só envia mensagens dentro desta janela. Fora dela, a resposta fica agendada para a próxima abertura — você vê o motivo na conversa.":
    "The assistant only sends messages within this window. Outside of it, the response is scheduled for the next opening — you see the reason in the conversation.",
  "Enviar aos domingos": "Send on Sundays",
  "Ligado por padrão: quem escreve no domingo espera resposta no domingo. Desligue se você faz prospecção ativa e prefere não incomodar no fim de semana.":
    "On by default: those who write on Sunday expect a response on Sunday. Turn it off if you do active prospecting and prefer not to bother them on the weekend.",
