  "Do jeito que está, esta cor não chegaria à tela: o sistema continuaria com a cor que já usa.":
    "As it is, this color would not reach the screen: the system would continue with the color it already uses.",
  "O que isto ainda não muda": "What this still doesn't change",
  "O título da aba do navegador continua com o nome do sistema, e não com o da sua empresa.":
    "The title of the browser tab continues with the system name, not your company name.",
  "A tela de entrada é sempre a do sistema: quando alguém digita a senha, ainda não dá para saber de qual empresa ele é.":
    "The entry screen is always the system one: when someone enters the password, it is still not possible to know which company they are from.",
  "Os e-mails que este sistema envia (convite de time, pedidos de LGPD) já saem com o nome da sua empresa.":
    "The emails that this system sends (team invitations, LGPD requests) already come out with your company name.",
  "O aplicativo de verificação em duas etapas continua registrando o nome do sistema: o cadastro acontece antes de saber de qual empresa a pessoa é.":
    "The two-step verification application continues to register the system name: registration takes place before knowing which company the person is from.",
  "O logo que você subir aqui aparece no menu lateral, para quem trabalha nesta empresa. A tela de entrada continua com o logo de quem instalou o sistema: ali ainda não dá para saber de qual empresa a pessoa é.":
    "The logo you go up here appears in the side menu, for those who work at this company. The entry screen continues with the logo of whoever installed the system: there it is still not possible to know which company the person is from.",
