  "Só uma etapa pode ser a de perda. Marcar esta desmarca":
    "Only one stage can be loss. Check this uncheck",
  "saiu do quadro.": "left the frame.",
  "entrou no fim do funil.": "entered the end of the funnel.",
  "Etapas deste funil": "Stages of this funnel",
  "Estas são as colunas do seu quadro, na ordem em que o cliente avança. Você pode renomear, criar, reordenar e arquivar.":
    "These are the columns on your board, in the order the customer progresses. You can rename, create, reorder and archive.",
  "Duas colunas têm papel especial: a": "Two columns have a special role: the",
  "de fechamento": "closing",
  "é onde o negócio vira venda, e a": "is where the business becomes sales, and the",
  "de perda": "of loss",
  "é onde ele se perde. Cada funil precisa de uma de cada — por isso a marcação se muda de lugar, não se apaga.":
    "That's where he gets lost. Each funnel needs one of each — that's why the marking moves around, it doesn't get erased.",
  Mover: "Move",
  "uma coluna para trás": "one column backwards",
  "uma coluna para frente": "one column forward",
  "no funil": "in the funnel",
  "O assistente usa esta etapa para": "The wizard uses this step to",
  "Mudar isso": "Change it",
  "Marcar mesmo assim": "Mark anyway",
  "A coluna sai do quadro e para de receber negócios novos. Nada é apagado — o histórico de quem passou por ela continua guardado —, mas":
    "The column leaves the board and stops receiving new business. Nothing is erased — the history of those who passed through it remains saved — but",
  "não dá para trazer a coluna de volta por aqui": "Can't bring the column back here",
  "está nesta etapa e não há outra coluna em aberto para recebê-lo.":
    "is at this stage and there is no other column open to receive it.",
  "estão nesta etapa e não há outra coluna em aberto para recebê-los.":
    "are at this stage and there is no other column open to receive them.",
