    "You registered the number with Meta and have the credentials in hand. Do not use your cell phone to connect.",
  "Contrato de um provedor parceiro": "Agreement from a partner provider",
  "Uma empresa parceira cuida do seu WhatsApp e te deu uma chave de acesso.":
    "A partner company takes care of your WhatsApp and gave you an access key.",
  "Este servidor ainda não está pronto para RECEBER por este caminho.":
    "This server is not yet ready to RECEIVE this way.",
  "Dá para conectar e já enviar, mas as respostas do cliente não vão chegar até quem instalou o sistema completar uma configuração no servidor. Se você quer atender hoje, o caminho do código com o celular funciona agora — e dá para trocar depois, sem perder nada.":
    "You can connect and send, but the client's responses will not arrive until whoever installed the system completes a configuration on the server. If you want to answer today, the code route with your cell phone works now — and you can change it later, without losing anything.",
