  "Google Agenda desta instalação": "Google Calendar from this installation",
  "Com estas duas informações, quem atende consegue conectar a agenda pessoal do Google e ver os compromissos do CRM lá. Elas valem para a instalação inteira — cada pessoa conecta a conta dela depois, sozinha.":
    "With these two pieces of information, whoever serves can connect their personal Google calendar and see CRM appointments there. They apply to the entire installation — each person connects their account later, alone.",
  "Endereço de retorno": "Return address",
  "Já existe uma chave cadastrada. Deixe em branco para mantê-la, ou digite uma nova para substituir.":
    "There is already a registered key. Leave it blank to keep it, or enter a new one to replace it.",
  "Ela é guardada cifrada e nunca volta a aparecer nesta tela.":
    "It is stored encrypted and never appears again on this screen.",
  "Esta instalação já tem as credenciais no arquivo de configuração do servidor. O que você salvar aqui passa a valer no lugar delas; apagar o que está aqui faz o sistema voltar a usar as do arquivo.":
    "This installation already has the credentials in the server configuration file. What you save here will be valid in their place; Deleting what is here makes the system use those in the file again.",
  "Ao trocar uma credencial já em uso:": "When exchanging a credential already in use:",
  "quem já conectou a agenda vai precisar conectar de novo. O Google invalida as autorizações antigas quando o aplicativo muda — não há como evitar, e ninguém perde compromisso por isso.":
    "Anyone who has already connected the calendar will need to connect it again. Google invalidates old authorizations when the application changes — there's no way around it, and no one loses commitment because of it.",
  "Nunca configurado por aqui.": "Never configured here.",
  "Credenciais do Google salvas.": "Saved Google credentials.",
  "cifra indisponível nesta instalação (GUC app.nuvemshop_oauth_key ausente) — o segredo não foi gravado":
    "cipher unavailable in this installation (GUC app.nuvemshop_oauth_key missing) — secret was not written",
  "Falta cadastrar o aplicativo do Google desta instalação. Leva um minuto e você faz por aqui mesmo.":
    "The Google application for this installation remains to be registered. It takes a minute and you do it right here.",
  "O que ele consulta antes de responder": "What does he consult before responding?",
  "Marque o material do seu negócio que este assistente pode ler. Ele procura ali antes de responder, em vez de improvisar — e cita de onde tirou.":
    "Mark your business material that this assistant can read. He looks there before answering, instead of improvising — and quotes where he got it from.",
  "Você ainda não cadastrou nenhum material.": "You haven't registered any materials yet.",
  "Comece pelo que ele mais vai precisar": "Start with what he will need most",
  "— as perguntas que se repetem, e a política que você mais explica.":
    "— the questions that are repeated, and the politics that you explain most.",
  "ainda não preparado": "Not yet ready",
  "Sem nenhum material marcado, ele conversa normalmente — mas responde só com o que o modelo já sabe, e a ferramenta de busca nem entra na conversa dele.":
    "Without any material marked, he chats normally — but only responds with what the model already knows, and the search tool doesn't even enter his conversation.",
