  "Inscrições e versões deste fluxo são apagadas junto. Não é possível desfazer.":
    "Subscriptions and versions of this stream are deleted together. Cannot undo.",
  "Follow-ups reengajam contatos após silêncio, mudança de etapa, uma regra em Webhooks ou a resposta do contato — sem depender de alguém lembrar de mandar mensagem.":
    "Follow-ups re-engage contacts after silence, change of stage, a rule in Webhooks or the contact's response — without depending on someone remembering to send a message.",
  "Fluxos automáticos de reengajamento — silêncio, etapa, webhook ou resposta do contato, sem intervenção em cada mensagem.":
    "Automatic re-engagement flows — silence, step, webhook or contact response, without intervention in each message.",
  "Nenhum material ainda.": "No materials yet.",
  "O agente ainda não conhece o seu negócio": "The agent doesn't know your business yet",
  "Comece pelo que ele mais vai precisar: as perguntas que se repetem, e a política que você mais explica. Ele passa a consultar isso antes de responder, em vez de improvisar.":
    "Start with what he will need most: the questions that are repeated, and the policy that you explain most. He starts to consult this before responding, instead of improvising.",
  "Material arquivado não é consultado por nenhum assistente, e não é apagado — o histórico do que o agente já soube continua existindo.":
    "Archived material is not consulted by any assistant, and is not deleted — the history of what the agent already knew continues to exist.",
  "O material do seu negócio que os assistentes consultam antes de responder. Cada assistente escolhe, na tela dele, o que pode ler daqui.":
    "Your business material that assistants consult before responding. Each assistant chooses, on his screen, what he can read from here.",
  " — edição bloqueada.": "— edit blocked.",
  "O navegador bloqueou as notificações. Libere-as nas configurações do site e recarregue.":
    "The browser blocked notifications. Release them in site settings and reload.",
  "Email ainda não está disponível. In-app (toast) e Push (Chrome) já funcionam para as cinco categorias, inclusive com a aba fechada.":
    "Email is not yet available. In-app (toast) and Push (Chrome) already work for the five categories, even with the tab closed.",
  "Nesta instalação, os avisos só aparecem com o site aberto.":
    "In this installation, the warnings only appear when the website is open.",
  "Ligar o Push abaixo já faz o aviso aparecer na bandeja do sistema enquanto você está com o site aberto numa aba. Para receber também com a aba fechada, quem administra o servidor precisa gerar um par de chaves uma única vez e reiniciar:":
    "Turning on Push below makes the warning appear in the system tray while you have the site open in a tab. To also receive with the tab closed, whoever administers the server needs to generate a pair of keys once and restart:",
  VAPID_PUBLIC_KEY: "VAPID_PUBLIC_KEY",
