  "Rótulo (Endereço)": "Label (Address)",
  "Opções, separadas por vírgula": "Options, separated by comma",
  "Sem janelas, o roteamento aceita conversa a qualquer hora — mas a Agenda não oferece NENHUM horário para marcar. Adicione janelas para publicar seus horários de atendimento.":
    "Without windows, routing accepts conversations at any time — but Calendar doesn't offer ANY times to schedule. Add windows to publish your opening hours.",
  "Nenhuma janela publicada — ninguém consegue marcar com esta pessoa.":
    "No window published — no one can make an appointment with this person.",
  "Atendentes e horários de atendimento": "Attendants and opening hours",
  "Status, carga e capacidade de cada atendente — e a jornada semanal que decide os horários oferecidos na Agenda. Sem ela ninguém consegue marcar.":
    "Status, load and capacity of each attendant — and the weekly journey that decides the times offered in the Agenda. Without it, no one can score.",
  "Só gerentes e administradores editam os horários de atendimento da equipe. Para publicar os seus, peça a um gerente que abra esta aba e use o botão &ldquo;Editar horário&rdquo; ao lado do seu nome.":
    "Only managers and administrators edit team office hours. To post yours, ask a manager to open this tab and use the “Edit schedule” button next to your name.",
  " — não publicado": "— unpublished",
  "Escolha um fluxo publicado": "Choose a published stream",
  "Nenhum fluxo ativo. Publique um follow-up em Follow-ups para usá-lo aqui.":
    "No active streams. Post a follow-up in Follow-ups to use it here.",
  "Só entram fluxos publicados e ativos.": "Only published and active flows enter.",
  "Sem eles ninguém consegue marcar — nem você, nem o agente.":
    "Without them, no one can score — not you, not the agent.",
  "Configurar meus horários de atendimento": "Configure my opening hours",
  "Não consegui carregar os horários": "I couldn't load the schedules",
  "Os dias ficam bloqueados até eu conseguir — é mais seguro que oferecer um horário que talvez não exista. Numa instalação nova, isso costuma ser a jornada de atendimento que ainda não foi publicada.":
    "The days are blocked until I can get it — it's safer than offering a time slot that might not exist. In a new facility, this tends to be the service journey that has not yet been published.",
  "Nenhum horário livre em": "No free time",
  "Os próximos 30 dias são o que está publicado hoje — meses adiante aparecem conforme a data se aproxima.":
    "The next 30 days are what's published today — months ahead appear as the date approaches.",
  "Conferindo a chave com a OpenAI — leva alguns segundos.":
    "Checking the key with OpenAI — takes a few seconds.",
  "Pronto para preparar material.": "Ready to prepare material.",
  "Falta uma chave da OpenAI para o agente aprender o seu material":
    "An OpenAI key is missing for the agent to learn its material",
  "Preparar um documento para o agente encontrá-lo usa a OpenAI, mesmo que o resto do seu assistente rode em outro provedor. Sem ela você consegue cadastrar o material, mas ele fica esperando — e o agente segue sem saber o que está nele.":
    "Preparing a document for the agent to find uses OpenAI, even if the rest of your assistant runs on another provider. Without it, you can register the material, but it waits — and the agent still doesn't know what's in it.",
  "Como você quer chamar esta chave": "What do you want to call this key",
