  "Aviso do assistente": "Assistant's warning",
  atenção: "attention",
  "O assistente prometeu algo ao cliente e ninguém ficou responsável":
    "The assistant promised something to the customer and no one was responsible",
  "Nesta conversa o assistente combinou algo com o cliente. Ele ainda não tem nenhuma capacidade marcada para registrar isso no sistema, então nada foi agendado nem anotado. Abra a conversa para ver o que foi combinado — e, na tela do assistente, marque o que ele pode fazer.":
    "In this conversation, the assistant agreed something with the customer. It doesn't yet have any capacity scheduled to record this in the system, so nothing has been scheduled or noted. Open the conversation to see what was agreed — and, on the assistant's screen, mark what he can do.",
  "Nesta conversa o assistente combinou algo com o cliente e não registrou nenhum próximo passo para isso — não há retorno agendado. Abra a conversa, veja o que foi combinado e decida quem faz.":
    "In this conversation, the assistant agreed something with the client and did not register any next steps for this — there is no scheduled return. Open the conversation, see what was agreed and decide who will do it.",
  "Nesta conversa o assistente combinou algo com o cliente, e a parte que organiza o sistema não rodou neste atendimento. Nada foi agendado. Abra a conversa para ver o que foi combinado e decida quem faz.":
    "In this conversation, the assistant agreed something with the customer, and the part that organizes the system did not run this service. Nothing was scheduled. Open the conversation to see what was agreed and decide who does it.",
