  Trecho: "Excerpt",
  "Uma tela não folheia mil pedaços — o restante está no acervo e o agente alcança todos.":
    "A screen does not leaf through a thousand pieces — the rest is in the collection and the agent reaches them all.",
  "Perguntas e respostas": "Questions and answers",
  "As dúvidas que se repetem, com a resposta pronta. É o formato que o agente cita melhor, porque cada resposta chega inteira.":
    "The doubts that are repeated, with the answer ready. It is the format that the agent quotes best, because each response arrives in one piece.",
  "Um texto do seu negócio — política de troca, tabela de preços, manual, contrato. Envie o arquivo (PDF, Markdown ou texto) ou cole o conteúdo.":
    "A text of your business — exchange policy, price list, manual, contract. Upload the file (PDF, Markdown or text) or paste the content.",
  "Conversas anteriores": "Previous conversations",
  "Atendimentos já resolvidos que alguém marcou como aproveitáveis, com os dados pessoais removidos.":
    "Already resolved calls that someone marked as usable, with personal data removed.",
  "Entra sozinha: conversas resolvidas que alguém marcar como aproveitáveis pela IA são anonimizadas e indexadas em lote.":
    "Enter alone: ​​resolved conversations that someone marks as usable by AI are anonymized and indexed in batch.",
  "Catálogo de produtos": "Product catalog",
  Moeda: "Currency",
  "Vale para todo preço do catálogo. Produto já cadastrado guarda a moeda com que nasceu.":
    "Valid for all catalog prices. Already registered product saves the currency with which it was born.",
  "Os produtos sincronizados da sua loja, com preço, descrição e disponibilidade.":
    "Synchronized products from your store, with price, description and availability.",
  "Entra sozinho: os produtos vêm da sincronização com a sua loja, não de conteúdo digitado aqui.":
    "Enter alone: products come from synchronization with your store, not from content entered here.",
