  "Meta Ads": "Meta Ads",
  "O desempenho das campanhas que estão trazendo gente para cá. Os números vêm da plataforma no momento em que você clica em Atualizar — nada fica guardado aqui.":
    "The performance of the campaigns that are bringing people here. The numbers come from the platform the moment you click Update — nothing is stored here.",
