  "Instalações do app": "App installations",
  "A plataforma recusou o token de acesso — ele expirou ou foi revogado. Gere um novo em Configurações › Meta Ads.":
    "The platform refused the access token — it has expired or been revoked. Generate a new one in Settings › Meta Ads.",
  "O token não tem permissão de leitura de anúncios (ads_read), ou não alcança esta conta. Refaça o token no Meta for Developers marcando essa permissão.":
    "The token does not have permission to read ads (ads_read), or it does not reach this account. Re-token in Meta for Developers by checking this permission.",
  "A plataforma limitou as chamadas por excesso de consultas. Espere alguns minutos antes de atualizar de novo.":
    "The platform limited calls due to excessive queries. Wait a few minutes before updating again.",
  "A plataforma recusou um campo desta consulta. Isso é um problema do sistema, não da sua conta — avise quem mantém a instalação.":
    "The platform refused a field in this query. This is a system problem, not your problem — let whoever maintains the installation know.",
  "A chave de criptografia da instalação não está disponível, então o token guardado não pode ser lido. Isso é configuração do servidor.":
    "The installation encryption key is not available, so the stored token cannot be read. This is server configuration.",
  "Não consegui falar com a plataforma agora. Tente atualizar em instantes.":
    "I was unable to speak to the platform now. Try updating in a moment.",
  "Seu papel não permite ver os dados de anúncios.": "Your role doesn't allow you to see ad data.",
  "Conecte um token de acesso para o sistema ler o desempenho das suas campanhas e mostrá-lo em Análise › Meta Ads. É uma conexão só de leitura: nada é criado, pausado ou alterado na sua conta de anúncios.":
    "Connect an access token for the system to read the performance of your campaigns and show it in Analysis › Meta Ads. It's a read-only connection: nothing is created, paused, or changed in your ad account.",
  "O token precisa da permissão ads_read. Gere-o no Meta for Developers, na sua conta de aplicativo, e cole abaixo — ele fica guardado criptografado e nunca é mostrado de volta.":
    "The token needs ads_read permission. Generate it in Meta for Developers, in your app account, and paste it below — it is stored encrypted and never shown back.",
  "Para trocar apenas a conta padrão, deixe o campo do token em branco — o token guardado é mantido.":
    "To switch just the default account, leave the token field blank — the saved token is kept.",
  "Guardado — preencha só para trocar": "Saved - fill in only to exchange",
  "Já existe um token guardado. Deixe em branco para mantê-lo, ou cole um novo para substituir.":
    "There is already a token saved. Leave it blank to keep it, or paste a new one to replace it.",
  "Precisa da permissão ads_read.": "Need ads_read permission.",
  "Conta padrão (opcional)": "Standard account (optional)",
  "A conta que a tela de Meta Ads abre por padrão. Em branco, ela abre a primeira conta ativa que o token alcançar.":
    "The account that the Meta Ads screen opens by default. Blank, it opens the first active account the token reaches.",
  "Cole o token para poder salvar.": "Paste the token to be able to save.",
  "Conta desconectada.": "Account disconnected.",
  "Desconectar apaga o token guardado. A tela de Meta Ads volta a pedir uma conexão, e nenhum dado histórico é perdido — nada é armazenado aqui.":
    "Disconnecting deletes the saved token. The Meta Ads screen asks for a connection again, and no historical data is lost — nothing is stored here.",
  "Não consegui desconectar agora.": "I couldn't disconnect now.",
  "Você não está em nenhuma organização ativa.": "You are not in any active organization.",
  "Só um administrador da organização pode mudar esta conexão.":
    "Only an organization administrator can change this connection.",
  "Confirme o segundo fator para salvar esta mudança.":
    "Confirm the second factor to save this change.",
  "Esta instalação está sem a chave mestra de criptografia, e o token não foi gravado. Quem instalou o sistema precisa configurá-la — refazer o cadastro aqui não resolve.":
    "This installation is missing the master encryption key, and the token has not been written. Whoever installed the system needs to configure it — re-registering here won't solve the problem.",
  "Não consegui gravar agora. Tente de novo em instantes.":
    "I couldn't record now. Please try again in a moment.",
  Conversões: "Conversions",
  "Quando um negócio que veio de anúncio é marcado como ganho, o valor da venda volta para a plataforma que trouxe o cliente. É esse retorno que ensina o anúncio a procurar mais gente parecida com quem comprou.":
    "When a deal that came from an ad is marked as won, the sale value goes back to the platform that brought the customer. It is this return that teaches the ad to look for more people similar to those who purchased.",
  "O envio está pausado. As vendas continuam sendo registradas aqui, mas não vão para a plataforma enquanto isto estiver desligado.":
    "Shipping is paused. Sales continue to be recorded here, but will not go to the platform while this is turned off.",
  "Modo de teste ligado: as vendas vão marcadas como teste e não contam para a otimização. Apague o código de teste quando terminar de conferir.":
    "Test mode on: sales are marked as test and do not count towards optimization. Delete the test code when you are finished checking.",
  "Vendas que não foram reportadas": "Sales that were not reported",
  "reportadas com sucesso": "successfully reported",
  "Nenhuma pendência. Ou tudo que veio de anúncio foi reportado, ou ainda não fechou nenhuma venda com origem em anúncio.":
    "No pending issues. Either everything that came from the ad was reported, or no sales were closed yet as a result of the ad.",
