  "Só números. Você encontra no gerenciador de anúncios, na fonte de dados que recebe as conversões.":
    "Just numbers. You can find it in the ads manager, in the data source that receives the conversions.",
  "Gravado. Deixe em branco para manter.": "Recorded. Leave blank to keep.",
  "Cole o token gerado na plataforma": "Paste the generated token into the platform",
  "Guardado criptografado. Ele nunca volta para esta tela depois de salvo.":
    "Stored encrypted. It never returns to this screen once saved.",
  "Código de teste (opcional)": "Test code (optional)",
  "Enquanto preenchido, as vendas vão marcadas como teste e não contam para a otimização. Apague quando terminar de conferir.":
    "While completed, sales are marked as testing and do not count towards optimization. Delete when you're done checking.",
